class Solution {
    public long smallestWithZeros(long zeros) {
        if (zeros == 0) return 0;
        long hi = 1;
        while (count(hi) < zeros) hi *= 2;
        long lo = hi / 2;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (count(mid) >= zeros) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    private long count(long n) {
        long total = 0;
        while (n > 0) { n /= 5; total += n; }
        return total;
    }
}

